{"implementation": "import json

def solve(case):
    nodes = case.get('nodes')
    required_symbols = case.get('required_symbols')
    if not isinstance(nodes, list) or not isinstance(required_symbols, list):
        raise ValueError('Invalid case: nodes and required_symbols must be lists')

    node_by_id = {}
    children = {}
    root_id = None
    for node in nodes:
        nid = node['id']
        node_by_id[nid] = node
        parent = node.get('parent')
        if parent is None:
            if root_id is not None:
                raise ValueError('Multiple roots')
            root_id = nid
        else:
            children.setdefault(parent, []).append(nid)

    if root_id is None:
        raise ValueError('No root node found')

    # Nodes whose symbols are required (cannot be removed)
    required_nodes = set()
    for nid, node in node_by_id.items():
        if node['symbol'] in required_symbols:
            required_nodes.add(nid)

    # Precompute subtree_has_required using reverse DFS (post-order)
    order = []
    stack = [root_id]
    visited = set()
    while stack:
        nid = stack.pop()
        if nid in visited:
            continue
        visited.add(nid)
        order.append(nid)
        for child in children.get(nid, []):
            stack.append(child)

    subtree_required = {nid: (nid in required_nodes) for nid in node_by_id}
    for nid in reversed(order):
        for child in children.get(nid, []):
            if subtree_required[child]:
                subtree_required[nid] = True
                break

    # Sort nodes by depth descending, then ID ascending
    depth_id_list = [(node['depth'], node['id']) for node in nodes]
    depth_id_list.sort(key=lambda x: (-x[0], x[1]))

    removed = set()
    removal_order = []

    for depth, nid in depth_id_list:
        node = node_by_id[nid]
        # Never remove root
        if node['parent'] is None:
            continue
        # Not removable
        if not node['removable']:
            continue
        # Symbol is required
        if node['symbol'] in required_symbols:
            continue
        # Has retained children (children not yet removed)
        if any(child not in removed for child in children.get(nid, [])):
            continue
        # Subtree contains a required symbol
        if subtree_required[nid]:
            continue
        # All conditions satisfied -> remove
        removed.add(nid)
        removal_order.append(nid)

    retained = sorted(nid for nid in node_by_id if nid not in removed)
    return {'removed_node_ids': removal_order, 'retained_node_ids': retained}"}
